// Space Dodger – minimal canvas game
// Canvas element with id="game" must exist in the HTML.
(() => {
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const resize = () => { canvas.width = canvas.offsetWidth; canvas.height = canvas.offsetHeight; };
  window.addEventListener('resize', resize);
  resize();

  // Player ship
  const ship = { x: canvas.width / 2, y: canvas.height * 0.8, w: 20, h: 30, speed: 4 };
  const keys = {};
  window.addEventListener('keydown', e => { keys[e.key] = true; });
  window.addEventListener('keyup', e => { keys[e.key] = false; });

  // Obstacles (asteroids)
  const obstacles = [];
  let spawnTimer = 0;
  let lastTime = performance.now();
  let score = 0;
  let gameOver = false;

  const update = dt => {
    // Input – arrow keys or WASD
    if (keys.ArrowLeft || keys.a) ship.x -= ship.speed;
    if (keys.ArrowRight || keys.d) ship.x += ship.speed;
    if (keys.ArrowUp || keys.w) ship.y -= ship.speed;
    if (keys.ArrowDown || keys.s) ship.y += ship.speed;
    // Keep ship inside canvas
    ship.x = Math.max(0, Math.min(canvas.width - ship.w, ship.x));
    ship.y = Math.max(0, Math.min(canvas.height - ship.h, ship.y));

    // Spawn obstacles
    spawnTimer -= dt;
    if (spawnTimer <= 0) {
      const size = 15 + Math.random() * 20;
      obstacles.push({ x: Math.random() * (canvas.width - size), y: -size, r: size / 2, vy: 2 + score * 0.02 });
      spawnTimer = 800 - Math.min(600, score * 10); // faster spawns over time
    }

    // Move obstacles
    for (let i = obstacles.length - 1; i >= 0; i--) {
      const o = obstacles[i];
      o.y += o.vy;
      if (o.y - o.r > canvas.height) obstacles.splice(i, 1);
    }

    // Collision detection (circle‑rect)
    for (const o of obstacles) {
      const cx = o.x + o.r;
      const cy = o.y + o.r;
      const rx = ship.x, ry = ship.y, rw = ship.w, rh = ship.h;
      const nearestX = Math.max(rx, Math.min(cx, rx + rw));
      const nearestY = Math.max(ry, Math.min(cy, ry + rh));
      const dx = cx - nearestX, dy = cy - nearestY;
      if (dx * dx + dy * dy < o.r * o.r) { gameOver = true; break; }
    }

    score += dt / 1000; // seconds
  };

  const draw = () => {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    // Background
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    // Ship – white triangle
    ctx.fillStyle = '#fff';
    ctx.beginPath();
    ctx.moveTo(ship.x + ship.w / 2, ship.y);
    ctx.lineTo(ship.x, ship.y + ship.h);
    ctx.lineTo(ship.x + ship.w, ship.y + ship.h);
    ctx.closePath();
    ctx.fill();
    // Obstacles
    ctx.fillStyle = '#888';
    for (const o of obstacles) {
      ctx.beginPath();
      ctx.arc(o.x + o.r, o.y + o.r, o.r, 0, Math.PI * 2);
      ctx.fill();
    }
    // Score
    ctx.fillStyle = '#0f0';
    ctx.font = '16px sans-serif';
    ctx.fillText('Score: ' + Math.floor(score), 10, 20);
    // Game over overlay
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.6)';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = '#f00';
      ctx.font = '48px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2);
    }
  };

  const loop = time => {
    const dt = time - lastTime;
    lastTime = time;
    if (!gameOver) update(dt);
    draw();
    if (!gameOver) requestAnimationFrame(loop);
  };

  // Start after DOM ready
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => requestAnimationFrame(loop));
  } else {
    requestAnimationFrame(loop);
  }
})();
